// Server-side view of the sector demos. src/sector-meta.json is generated by
// scripts/build-sectors.js from docs/secteurs/data/<slug>.js, so the labels,
// fictional company identities and e-mail vocabulary used in real e-mails
// can never drift from what the demo sites show. The slug arrives from a
// public form, so only known slugs resolve; anything else yields null.
const META = require("./sector-meta.json");

// `lang` picks the trade's label and e-mail vocabulary for EN/DE demos;
// the fictional company's identity is the same in every language.
function getSector(slug, lang) {
  if (!slug || !Object.prototype.hasOwnProperty.call(META, slug)) return null;
  const { i18n, ...base } = META[slug];
  const local = (i18n && i18n[lang]) || {};
  return { slug, ...base, ...local };
}

function sectorLabel(slug) {
  const s = getSector(slug);
  return s ? s.label : "";
}

// Marketplaces/partners a private demo is staged for. Only these exact keys
// are accepted from the browser, so the name shown in e-mails cannot be
// chosen by a visitor.
const PLATFORMS = { "devis-ch": "devis.ch" };

function platformName(key) {
  return key && Object.prototype.hasOwnProperty.call(PLATFORMS, key) ? PLATFORMS[key] : "";
}

module.exports = { getSector, sectorLabel, platformName };
